content.text:
{
  "name": "Seeed USB-CAN 分析仪",
  "name_en": "Seeed USB-CAN Analyzer",
  "manufacturer": "Seeed Studio",
  "description": "用于通过 USB 将计算机连接到 CAN 总线的硬件接口设备，可完成总线初始化、状态查询与 CAN 报文发送，适合实验中的设备联调、协议通信和总线监测。",
  "description_en": "A hardware interface device that connects a computer to a CAN bus over USB. It supports bus initialization, status queries, and CAN message transmission for laboratory device integration, protocol communication, and bus monitoring.",
  "actions": [
    {
      "action_name": "auto-shutdown",
      "description": "关闭 USB-CAN 分析仪的串口通信接口。",
      "description_en": "Close the USB-CAN analyzer serial communication interface."
    },
    {
      "action_name": "auto-init_frame",
      "description": "发送初始化帧以配置设备并开始 CAN 通信。",
      "description_en": "Send an initialization frame to configure the device and start CAN communication."
    },
    {
      "action_name": "auto-flush_buffer",
      "description": "清空设备通信缓冲区以移除积压数据。",
      "description_en": "Flush the device communication buffer to remove queued data."
    },
    {
      "action_name": "auto-status_frame",
      "description": "发送状态查询帧以获取设备状态或错误信息。",
      "description_en": "Send a status request frame to obtain device status or error information."
    },
    {
      "action_name": "auto-send",
      "description": "通过 USB-CAN 分析仪发送 CAN 报文。",
      "description_en": "Send a CAN message through the USB-CAN analyzer."
    },
    {
      "action_name": "auto-fileno",
      "description": "获取底层通信接口的文件描述符。",
      "description_en": "Get the file descriptor of the underlying communication interface."
    }
  ],
  "tag_hints": [
    "USB-CAN interface",
    "CAN bus communication",
    "CAN message transmission",
    "serial-connected CAN adapter",
    "bus initialization",
    "device status query"
  ]
}

